        C = torch.empty((M, N), dtype=torch.float16, device=device)

        # Launch parameters
        threads_per_block = (16, 16, 1)   # matches BLOCK_ROWS/BLOCK_COLS = 8 each => 16x16 threads
        blocks_per_grid = (
            (N + 128 - 1) // 128,
            (M + 128 - 1) // 128,
        )

        # Call the CUDA kernel
        self._kernel(
            A.contiguous(),
            B.contiguous(),
            C,
            M,
            N,
            K,
            block=threads_per_block,
            grid=blocks_per_grid,
        )
        return C

